import{_ as o,o as a,c as d,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"公式プラグインのサンプル解説","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/examples.md","filePath":"ja-JP/dev-guide/examples.md","lastUpdated":1787586465000}'),r={name:"ja-JP/dev-guide/examples.md"};function c(l,e,t,n,s,h){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="公式プラグインのサンプル解説" tabindex="-1">公式プラグインのサンプル解説 <a class="header-anchor" href="#公式プラグインのサンプル解説" aria-label="Permalink to &quot;公式プラグインのサンプル解説&quot;">​</a></h1><p><code>Lertaro.PluginSdk</code> の各インターフェイスの連携を深く理解するために、公式リポジトリに同梱されている 3 つの代表的なプラグインの実装パターンを解説します。</p><h2 id="_1-coreextensions-——-アクション、shell-メニュー、クイックパネル" tabindex="-1">1. CoreExtensions —— アクション、Shell メニュー、クイックパネル <a class="header-anchor" href="#_1-coreextensions-——-アクション、shell-メニュー、クイックパネル" aria-label="Permalink to &quot;1. CoreExtensions —— アクション、Shell メニュー、クイックパネル&quot;">​</a></h2><p><code>CoreExtensions</code> は Lertaro の中心的な拡張機能であり、<code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code>、および複数のプロバイダーを実装しています。</p><h3 id="主な実装ポイント" tabindex="-1">主な実装ポイント <a class="header-anchor" href="#主な実装ポイント" aria-label="Permalink to &quot;主な実装ポイント&quot;">​</a></h3><ul><li><strong>静的アクション（<code>IActionProvider.GetActions()</code>）</strong>：開く、エクスプローラーで表示、パスクリップボードコピー、ファイルのコピー/切り取り、コマンドプロンプトで開く、管理者として実行など、10 個の基本アクションを提供。</li><li><strong>Shell コンテキストメニュー統合（<code>IDynamicActionProvider</code>）</strong>：<code>ShellMenuActionProvider</code> を介して Windows Shell の COM インターフェイスと連携し、階層化された右クリックメニュー（「送る」、7-Zip、VS Code など）を <code>Ctrl+O</code> アクションメニュー内に忠実に描画。</li><li><strong>スキーマ駆動の設定フォーム（<code>IConfigurable</code>）</strong>：グループ化（<code>Group</code>）、文字列リスト（<code>StringList</code>）、ホットキー登録（<code>Hotkey</code>）を含むフォームスキーマを定義し、XAML を書かずに設定センターへ UI を自動生成。</li><li><strong>多彩なクイックパネルタブ（<code>IQuickPanelTabProvider</code>）</strong>： <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>：メモリ上のデータをそのまま結果として返し、ディスク I/O を発生させない最小構成。</li><li><code>WindowsRecentTabProvider</code>：バックグラウンドで <code>Recent</code> フォルダーを巡回し、COM でショートカットのリンク先を解決して <code>Metadata.Modified</code> を付与。</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>：ホストが公開している <a href="./sdk/services.html"><code>ExplorerPathService</code></a> や <code>RecentFilesService</code> を直接参照。</li></ul></li></ul><h2 id="_2-pinyinalias-——-非-ascii-エイリアス変換エンジン" tabindex="-1">2. PinyinAlias —— 非 ASCII エイリアス変換エンジン <a class="header-anchor" href="#_2-pinyinalias-——-非-ascii-エイリアス変換エンジン" aria-label="Permalink to &quot;2. PinyinAlias —— 非 ASCII エイリアス変換エンジン&quot;">​</a></h2><p><code>PinyinAlias</code> は、中国語ファイル名に対するピンイン全スペルおよび頭文字検索をサポートし、<code>IAliasProvider</code> と <code>ITranslationProvider</code> を実装しています。</p><h3 id="主な実装ポイント-1" tabindex="-1">主な実装ポイント <a class="header-anchor" href="#主な実装ポイント-1" aria-label="Permalink to &quot;主な実装ポイント&quot;">​</a></h3><ul><li><strong>文字境界の宣言（<code>InputRanges</code> / <code>OutputRanges</code>）</strong>：入力元を CJK 統合漢字、出力先を英小文字 <code>a</code>–<code>z</code> と定義。ホストはこの情報をもとに、漢字とアルファベットが混在したクエリを字面一致とピンイン一致に自動分割。</li><li><strong>事前高速判定（<code>CanHandle(text)</code>）</strong>：文字列中に該当文字が含まれるかを事前に走査し、英数字のみの場合は即座に <code>false</code> を返して不要な処理をスキップ。</li><li><strong>多音字の組み合わせ生成（<code>GetAliases(text)</code>）</strong>：音節マップを構築し、複数の読みが存在する場合にパイプ記号 <code>|</code> で連結した候補群を最大 32 通りまで生成して並列照合。</li><li><strong>多言語リソースとスレッドセーフなキャッシュ</strong>：<code>ITranslationProvider</code> を通じてプラグインの表示名を多言語化し、内部では <code>lock</code> 付きディクショナリで JSON をキャッシュして高速化。</li></ul><h2 id="_3-flowlauncherbridge-——-コミュニティプラグインの相互運用" tabindex="-1">3. FlowLauncherBridge —— コミュニティプラグインの相互運用 <a class="header-anchor" href="#_3-flowlauncherbridge-——-コミュニティプラグインの相互運用" aria-label="Permalink to &quot;3. FlowLauncherBridge —— コミュニティプラグインの相互運用&quot;">​</a></h2><p><code>FlowLauncherBridge</code> は、外部の Flow Launcher プラグインをネイティブレベルで透過的に動かすための大規模ブリッジプラグインです。</p><h3 id="主な実装ポイント-2" tabindex="-1">主な実装ポイント <a class="header-anchor" href="#主な実装ポイント-2" aria-label="Permalink to &quot;主な実装ポイント&quot;">​</a></h3><ul><li><strong>マルチ言語プロセス間ブリッジ</strong>：C# (.NET)、Python 3.12、Node.js v20 LTS、および <code>.exe</code> 形式の Flow プラグインを実行。</li><li><strong>隔離された自己完結ランタイム</strong>：ユーザーデータフォルダー内に Python / Node.js ランタイムを自動配置し、名前付きパイプによる JSON-RPC 通信を実行。</li><li><strong>動的設定フォームと WebView2 リッチプレビュー</strong>：外部プラグインの <code>SettingsTemplate.yaml</code>/<code>.json</code> を <code>PluginConfigSchema</code> に動的変換し、辞書や天気などのリッチな HTML プレビューを QuickLook 内に表示。</li></ul>',14)])])}const P=o(r,[["render",c]]);export{g as __pageData,P as default};
